<div x-data="rmExpertResidentGraph(@js($grafoLectura))" class="rm-expert-read-map">
    <p class="rm-expert-guide">El mapa enfoca el dato seleccionado y sus conexiones. El detalle permanece a su lado; todos los registros siguen disponibles en la lista.</p>
    <div class="rm-lab-actions"><button type="button" class="rm-btn rm-btn-secondary" @click="zoom(-.15)" aria-label="Reducir mapa del expediente">−</button><button type="button" class="rm-btn rm-btn-secondary" @click="zoom(.15)" aria-label="Ampliar mapa del expediente">+</button><button type="button" class="rm-btn rm-btn-secondary" @click="centrar()">Ajustar sin reducir texto</button><button type="button" class="rm-btn rm-btn-secondary" @click="enfocarConexiones()" :aria-pressed="focoVecindario">Solo conexiones seleccionadas</button></div>
    <nav class="rm-lab-actions" x-show="paginarFuentes" aria-label="Páginas del mapa de fuentes"><button type="button" class="rm-btn rm-btn-secondary" @click="cambiarPaginaFuente(paginaFuentes - 1)" :disabled="paginaFuentes <= 1">Anteriores</button><span x-text="'Página ' + paginaFuentes + ' de ' + paginasFuentes"></span><button type="button" class="rm-btn rm-btn-secondary" @click="cambiarPaginaFuente(paginaFuentes + 1)" :disabled="paginaFuentes >= paginasFuentes">Siguientes</button></nav>
    <div class="rm-expert-read-map__layout">
        <x-ui.expert-graph-canvas class="rm-knowledge-canvas" label="Conexiones documentadas del expediente" />
        <aside class="rm-expert-source-detail" aria-label="Campos del registro junto al mapa" aria-live="polite"><h4 x-text="actual?.nombre ?? 'Seleccione un registro'"></h4><p x-text="actual?.estado"></p><dl class="rm-lab-data"><template x-for="(valor, etiqueta) in actual?.datos || {}" :key="etiqueta"><div><dt x-text="etiqueta"></dt><dd x-text="valor ?? 'No disponible'"></dd></div></template></dl></aside>
    </div>
    <details class="rm-expert-source-detail"><summary>Lista accesible de registros y relaciones</summary><div class="rm-expert-record__links"><template x-for="n in nodos" :key="n.id"><button type="button" @click="seleccionar(n.id)"><span><strong x-text="n.nombre"></strong><small x-text="n.estado"></small></span></button></template></div></details>
</div>
